// What the query world (blitzphysics.cpp) and the simulation worlds (simulation.cpp) have in common: the set up of Jolt, the
// ellipsoid, meshes and the conversions of the C interface.
#pragma once

#include <Jolt/Jolt.h>

#include <Jolt/Core/Factory.h>
#include <Jolt/Physics/Body/BodyID.h>
#include <Jolt/Physics/Collision/CollideSoftBodyVertexIterator.h>
#include <Jolt/Physics/Collision/Shape/ConvexShape.h>
#include <Jolt/Physics/Collision/Shape/Shape.h>
#include <Jolt/RegisterTypes.h>

#include <algorithm>
#include <atomic>
#include <cmath>
#include <cstdint>

// Jolt is set up while any world, mesh or simulation exists.
void jolt_acquire();
void jolt_release();

struct bp_mesh {
	JPH::RefConst<JPH::Shape> shape;
	std::atomic<uint32_t>     users{ 1 };
};

inline void release_mesh(bp_mesh* mesh)
{
	if (mesh && (mesh->users.fetch_sub(1) == 1)) {
		delete mesh;
		jolt_release();
	}
}

inline JPH::Vec3 to_vec(const float* v) { return JPH::Vec3(v[0], v[1], v[2]); }

inline JPH::Quat to_quat(const float* q)
{
	JPH::Quat r(q[0], q[1], q[2], q[3]);
	return (r.LengthSq() > 1e-12f) ? r.Normalized() : JPH::Quat::sIdentity();
}

namespace bp_shapes {
using namespace JPH;

////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
// The ellipsoid is a convex shape of its own, through the place that Jolt has for them (UserConvex1): all of Jolt's casts and
// collisions of convex shapes work with it, against meshes as well.
////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
class ellipsoid_shape final : public ConvexShape {
	public:
	explicit ellipsoid_shape(Vec3Arg radii) : ConvexShape(EShapeSubType::UserConvex1), radii(radii) {}

	struct support final : public Support {
		Vec3 radii;
		explicit support(Vec3Arg radii) : radii(radii) {}
		Vec3  GetSupport(Vec3Arg direction) const override
		{
			Vec3  scaled = radii * direction;
			float length = scaled.Length();
			return (length > 0.0f) ? (radii * scaled) / length : Vec3::sZero();
		}
		float GetConvexRadius() const override { return 0.0f; }
	};

	const Support* GetSupportFunction(ESupportMode, SupportBuffer& buffer, Vec3Arg scale) const override { return new (&buffer) support(radii * scale.Abs()); }
	AABox          GetLocalBounds() const override { return AABox(-radii, radii); }
	float          GetInnerRadius() const override { return std::min(radii.GetX(), std::min(radii.GetY(), radii.GetZ())); }
	// A solid ellipsoid of density 1: the mass is the volume, the inertia is that of the three axes.
	MassProperties GetMassProperties() const override
	{
		MassProperties m;
		float          x = radii.GetX(), y = radii.GetY(), z = radii.GetZ();
		m.mMass    = GetVolume();
		m.mInertia = Mat44::sScale(Vec3(m.mMass / 5.0f * (y * y + z * z), m.mMass / 5.0f * (x * x + z * z), m.mMass / 5.0f * (x * x + y * y)));
		return m;
	}
	Vec3 GetSurfaceNormal(const SubShapeID&, Vec3Arg point) const override { return (point / (radii * radii)).NormalizedOr(Vec3::sAxisY()); }
	void GetSupportingFace(const SubShapeID&, Vec3Arg, Vec3Arg, Mat44Arg, SupportingFace&) const override {}
	void CollideSoftBodyVertices(Mat44Arg, Vec3Arg, const CollideSoftBodyVertexIterator&, uint, int) const override {}
#ifdef JPH_DEBUG_RENDERER
	void Draw(DebugRenderer*, RMat44Arg, Vec3Arg, ColorArg, bool, bool) const override {}
#endif
	Stats GetStats() const override { return Stats(sizeof(*this), 0); }
	float GetVolume() const override { return 4.0f / 3.0f * JPH_PI * radii.GetX() * radii.GetY() * radii.GetZ(); }

	private:
	Vec3 radii;
};
} // namespace bp_shapes
